// 1. Guava RateLimiter - 令牌桶限流
@Service
public class RateLimitService {
    private final RateLimiter limiter = RateLimiter.create(100); // 100 QPS

    public String process(String request) {
        if (!limiter.tryAcquire(100, TimeUnit.MILLISECONDS)) {
            throw new RateLimitException("请求过于频繁");
        }
        return doProcess(request);
    }
}

// 2. Redis 集群限流 - 滑动窗口
@Service
public class RedisRateLimiter {
    private final StringRedisTemplate redis;

    public boolean isAllowed(String key, int limit, int windowSeconds) {
        long now = System.currentTimeMillis();
        long windowStart = now - windowSeconds * 1000L;

        // Lua 脚本保证原子性：移除窗口外的成员、统计窗口内数量、判断是否放行
        String luaScript = "redis.call('zremrangebyscore', KEYS[1], 0, ARGV[1]) " +
            "local count = redis.call('zcard', KEYS[1]) " +
            "if count < tonumber(ARGV[3]) then " +
            "redis.call('zadd', KEYS[1], ARGV[2], ARGV[2]) " +
            "redis.call('expire', KEYS[1], ARGV[4]) " +
            "return 1 else return 0 end";

        Long result = redis.execute(
            new DefaultRedisScript<>(luaScript, Long.class),
            Collections.singletonList("rate:" + key),
            String.valueOf(windowStart),
            String.valueOf(now),
            String.valueOf(limit),
            String.valueOf(windowSeconds)
        );
        return Long.valueOf(1L).equals(result);
    }
}

// 3. Sentinel - 限流 + 熔断 + 降级一体化
@SentinelResource(
    value = "createOrder",
    blockHandler = "createOrderBlock",    // 限流/熔断触发时的处理
    fallback = "createOrderFallback"       // 业务异常时的 fallback
)
public OrderId createOrder(CreateOrderCmd cmd) {
    return orderService.create(cmd);
}

// blockHandler 处理限流和熔断异常（Sentinel 定义的 BlockException）
public OrderId createOrderBlock(CreateOrderCmd cmd, BlockException ex) {
    if (ex instanceof FlowException) {
        throw new RateLimitException("系统繁忙，请稍后重试");
    } else if (ex instanceof DegradeException) {
        return OrderId.degraded(); // 熔断时返回降级结果
    }
    throw new RateLimitException("请求被限制");
}

// fallback 处理业务异常
public OrderId createOrderFallback(CreateOrderCmd cmd, Throwable t) {
    return OrderId.pending(); // 返回待处理状态，异步补偿
}

// 4. Resilience4j 熔断器 - 函数式风格
@Service
public class CircuitBreakerService {
    private final CircuitBreakerConfig config = CircuitBreakerConfig.custom()
        .failureRateThreshold(50)                     // 错误率阈值 50%
        .slowCallRateThreshold(80)                    // 慢调用比例阈值 80%
        .slowCallDurationThreshold(Duration.ofMillis(500)) // 慢调用 RT 阈值 500ms
        .waitDurationInOpenState(Duration.ofSeconds(10))   // Open 状态等待 10 秒
        .permittedNumberOfCallsInHalfOpenState(5)     // Half-Open 放 5 个请求试探
        .slidingWindowSize(100)                       // 滑动窗口大小 100
        .build();
    private final CircuitBreaker cb = CircuitBreaker.of("orderService", config);

    public OrderDTO getOrderWithFallback(String orderId) {
        Supplier<OrderDTO> decorated = CircuitBreaker
            .decorateSupplier(cb, () -> orderClient.getOrder(orderId));
        return Try.ofSupplier(decorated)
            .recover(CallNotPermittedException.class, e -> {
                // 熔断打开时的 fallback
                log.warn("熔断器打开，返回降级结果");
                return OrderDTO.degraded();
            })
            .recover(Exception.class, e -> OrderDTO.error())
            .get();
    }
}
